def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by their digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = str(n)
        total = 0

        # Numbers with a zero digit have product zero and are always beautiful.
        # Count them by length, requiring a nonzero leading digit.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else "9" * length
            states = {(True, False): 1}
            for pos, ch in enumerate(bound):
                cap = int(ch)
                following = {}
                for (tight, has_zero), count in states.items():
                    limit = cap if tight else 9
                    for digit in range(1 if pos == 0 else 0, limit + 1):
                        key = (tight and digit == cap, has_zero or digit == 0)
                        following[key] = following.get(key, 0) + count
                states = following
            total += sum(count for (_, has_zero), count in states.items() if has_zero)

        # For numbers without zero, fix the digit sum and track the product
        # modulo that sum. A product is divisible by the sum exactly at residue 0.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else "9" * length
            for target_sum in range(length, 9 * length + 1):
                modulus = target_sum
                states = {(0, 1 % modulus, True): 1}
                for pos, ch in enumerate(bound):
                    cap = int(ch)
                    following = {}
                    for (digit_sum, product_mod, tight), count in states.items():
                        limit = cap if tight else 9
                        for digit in range(1, limit + 1):
                            new_sum = digit_sum + digit
                            if new_sum > target_sum:
                                continue
                            new_tight = tight and digit == cap
                            key = (new_sum, (product_mod * digit) % modulus, new_tight)
                            following[key] = following.get(key, 0) + count
                    states = following
                total += sum(count for (digit_sum, product_mod, _), count in states.items()
                             if digit_sum == target_sum and product_mod == 0)
        return total

    return count_up_to(r) - count_up_to(l - 1)

