MOD = 998244353
ROOT = 3


def _ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def _convolve(a, b):
    out_len = len(a) + len(b) - 1
    if min(len(a), len(b)) <= 32 or len(a) * len(b) <= 4096:
        out = [0] * out_len
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    out[i + j] = (out[i + j] + x * y) % MOD
        return out
    size = 1
    while size < out_len:
        size <<= 1
    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD
    _ntt(fa, True)
    return fa[:out_len]


def sum_concatenated_permutations(n: int) -> int:
    """Given a positive integer n, sum concatenated permutations modulo 998244353."""
    counts = {}
    sums = {}
    for x in range(1, n + 1):
        digits = len(str(x))
        counts[digits] = counts.get(digits, 0) + 1
        sums[digits] = sums.get(digits, 0) + x

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    polys = []
    bases = {}
    for digits, count in counts.items():
        base = pow(10, digits, MOD)
        bases[digits] = base
        poly = [0] * (count + 1)
        power = 1
        for k in range(count + 1):
            poly[k] = fact[count] * invfact[k] % MOD * invfact[count - k] % MOD * power % MOD
            power = power * base % MOD
        polys.append(poly)

    while len(polys) > 1:
        next_level = []
        for i in range(0, len(polys), 2):
            if i + 1 < len(polys):
                next_level.append(_convolve(polys[i], polys[i + 1]))
            else:
                next_level.append(polys[i])
        polys = next_level
    subset_weights = polys[0]

    total_value = n * (n + 1) // 2 % MOD
    q_prev = {digits: 1 for digits in counts}
    answer = 0
    for r in range(n):
        excluded_weight = total_value * subset_weights[r] % MOD
        if r:
            for digits, count in counts.items():
                base = bases[digits]
                excluded_weight -= (sums[digits] % MOD) * base % MOD * q_prev[digits] % MOD
                q_prev[digits] = (subset_weights[r] - base * q_prev[digits]) % MOD
        excluded_weight %= MOD
        answer = (answer + fact[r] * fact[n - r - 1] % MOD * excluded_weight) % MOD
    return answer

