def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return whether an n×n binary matrix can have exactly k fixed cells.

    Variable cells lie on alternating cycles of the bipartite graph formed
    by the matrix. Each nontrivial strongly connected component contains at
    least two row vertices and two column vertices; a component with r rows
    and c columns contributes r*c variable cells. Cells between components
    are fixed.
    """
    if k < 0 or k > n * n:
        return False

    variable = n * n - k
    # dp[r][c] is a bitset of variable-cell totals achievable using r row
    # vertices and c column vertices in nontrivial components.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    mask = (1 << (variable + 1)) - 1
    for rows_used in range(n + 1):
        for cols_used in range(n + 1):
            areas = dp[rows_used][cols_used]
            if not areas:
                continue
            for rows in range(2, n - rows_used + 1):
                for cols in range(2, n - cols_used + 1):
                    shift = rows * cols
                    if shift <= variable:
                        dp[rows_used + rows][cols_used + cols] |= (areas << shift) & mask
    return any((areas >> variable) & 1 for row in dp for areas in row)

