from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0
    si, sj, _ = start
    ti, tj, _ = target
    if max(abs(ti - si), abs(tj - sj)) <= 40 and K <= 100:
        todo = deque([(start, 0)])
        seen = {start}
        while todo:
            (i, j, k), d = todo.popleft()
            same = (i - j) % 2 == 0
            neighbors = []
            if k:
                neighbors.append((i, j, k - 1))
            if k + 1 < K:
                neighbors.append((i, j, k + 1))
            if same:
                neighbors.extend(((i - 1, j, K - 1), (i + 1, j, 0)))
                if k == 0:
                    neighbors.extend((i, j - 1, q) for q in range(K))
                if k == K - 1:
                    neighbors.extend((i, j + 1, q) for q in range(K))
            else:
                neighbors.extend(((i, j - 1, 0), (i, j + 1, K - 1)))
                if k == 0:
                    neighbors.extend((i - 1, j, q) for q in range(K))
                if k == K - 1:
                    neighbors.extend((i + 1, j, q) for q in range(K))
            for nxt in neighbors:
                if nxt == target:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    todo.append((nxt, d + 1))
    return (abs(T_x - S_x) + abs(T_y - S_y)) // K

