MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count ordered length-M sequences whose product is at most N and has
    divisor sum divisible by 3, modulo 998244353.

    The number of sequences with a fixed product n is the M-fold divisor
    function: for n = product(p**e), it is product(binomial(M+e-1, e)).
    """
    if N < 1 or M < 1:
        return 0

    # A segmented factorization keeps memory bounded while allowing each
    # integer's prime exponents and divisor-sum residue to be computed.
    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0: min(2, limit + 1)] = b"\x00" * min(2, limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p : limit + 1 : p] = b"\x00" * (((limit - p * p) // p) + 1)

    max_exp = N.bit_length()
    ways = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        ways[e] = ways[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    block_size = 1 << 17
    answer = 0
    for low in range(1, N + 1, block_size):
        high = min(N, low + block_size - 1)
        size = high - low + 1
        rem = list(range(low, high + 1))
        weight = [1] * size
        good = bytearray(size)

        for p in primes:
            if p * p > high:
                break
            first = ((low + p - 1) // p) * p
            for value in range(first, high + 1, p):
                idx = value - low
                exponent = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    exponent += 1
                if exponent:
                    weight[idx] = weight[idx] * ways[exponent] % MOD
                    if p % 3 == 2:
                        if exponent & 1:
                            good[idx] = 1
                    elif p != 3 and (exponent + 1) % 3 == 0:
                        good[idx] = 1

        for i, leftover in enumerate(rem):
            if leftover > 1:
                weight[i] = weight[i] * M % MOD
                if leftover % 3 == 2:
                    good[i] = 1

        for i in range(size):
            if good[i]:
                answer += weight[i]
        answer %= MOD

    return answer

