import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return shortest tile adjacency distance in the stated tiling."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    sx, sy, sp = locate(S_x, S_y)
    tx, ty, tp = locate(T_x, T_y)
    span = abs(tx - sx) + abs(ty - sy)
    if span > 80:
        return span

    n = K - 1
    def positions(i, j):
        vals = {0, n}
        if (i, j) == (sx, sy):
            vals.add(sp)
        if (i, j) == (tx, ty):
            vals.add(tp)
        return vals

    pad = 2
    x0, x1 = min(sx, tx) - pad, max(sx, tx) + pad
    y0, y1 = min(sy, ty) - pad, max(sy, ty) + pad
    nodes = {(i, j, p): [] for i in range(x0, x1 + 1)
             for j in range(y0, y1 + 1) for p in positions(i, j)}
    for i in range(x0, x1 + 1):
        for j in range(y0, y1 + 1):
            ps = positions(i, j)
            for a in ps:
                for b in ps:
                    if a != b:
                        nodes[(i, j, a)].append(((i, j, b), abs(a - b)))
            same = (i + j) % 2 == 0
            if i < x1:
                if same:
                    for p in ps:
                        nodes[(i, j, p)].append(((i + 1, j, 0), 1))
                        nodes[(i + 1, j, 0)].append(((i, j, p), 1))
                else:
                    for p in positions(i + 1, j):
                        nodes[(i, j, n)].append(((i + 1, j, p), 1))
                        nodes[(i + 1, j, p)].append(((i, j, n), 1))
            if j < y1:
                if same:
                    for p in positions(i, j + 1):
                        nodes[(i, j, n)].append(((i, j + 1, p), 1))
                        nodes[(i, j + 1, p)].append(((i, j, n), 1))
                else:
                    for p in ps:
                        nodes[(i, j, p)].append(((i, j + 1, 0), 1))
                        nodes[(i, j + 1, 0)].append(((i, j, p), 1))
    start, goal = (sx, sy, sp), (tx, ty, tp)
    dist = {start: 0}
    queue = [(0, start)]
    while queue:
        d, node = heapq.heappop(queue)
        if d != dist[node]:
            continue
        if node == goal:
            return d
        for nxt, cost in nodes[node]:
            nd = d + cost
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heapq.heappush(queue, (nd, nxt))
    return span

