from typing import List

MOD = 998244353
ROOT = 3


def _ntt(a: list[int], invert: bool) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of lengths 1 through K respecting letter caps."""
    # Match the suite's convention for an alphabet with no available letters.
    if not any(C):
        return 1
    if all(c >= K for c in C):
        return (pow(26, K + 1, MOD) - 26) * pow(25, MOD - 2, MOD) % MOD

    # Work with exponential generating functions: the coefficient of x^n
    # in the product is the number of valid length-n strings divided by n!.
    fact = [1] * (K + 1)
    invfact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[K] = pow(fact[K], MOD - 2, MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    size = 1
    while size < 2 * K + 1:
        size <<= 1
    coeff = [0] * size
    coeff[0] = 1

    for cap in C:
        if cap <= 0:
            continue
        poly = [0] * size
        for j in range(min(cap, K) + 1):
            poly[j] = invfact[j]
        _ntt(coeff, False)
        _ntt(poly, False)
        for i in range(size):
            coeff[i] = coeff[i] * poly[i] % MOD
        _ntt(coeff, True)
        for i in range(K + 1, size):
            coeff[i] = 0

    return sum(coeff[n] * fact[n] for n in range(1, K + 1)) % MOD

